------------ import ------------
------------ import ------------
local CommonTabToggleLeftExpandCell = "Game.Behaviours.CommonTabToggleLeftExpandCell"

---@class CommonTabToggleLeftExpand
---@field ListView                      	SuperScrollView.LoopListView2 @展出的列表
local CommonTabToggleLeftExpand = Class('CommonTabToggleLeftExpand')

function CommonTabToggleLeftExpand:__init()
    self._allPardata = {}    --所有的父节点数据
    self._allChilddata = {}  --所有的子节点数据
    self._curParInd = 0      --当前父节点选中下标
    self._curChildInd = 0    --当前子节点选中下标

    self._viewData = {}      --循环列表用的
    self._curSelectInd = 0 
end

function CommonTabToggleLeftExpand:__delete()
    self._allPardata = nil    --所有的父节点数据
    self._allChilddata = nil  --所有的子节点数据
    self._viewData = nil      --循环列表用的
    self._curParInd = nil      --当前父节点选中下标
    self._curChildInd = nil    --当前子节点选中下标
end

function CommonTabToggleLeftExpand:Awake()

end

---@param parData table @ 所有父节点数据
---@param childData table @ 所有子节点数据
---@param parInd integer @ 选中的父节点下标
---@param childInd integer @ 选中的子节点下标
function CommonTabToggleLeftExpand:Refresh(parData, childData, parInd, childInd)
    if not parData then
        return
    end
    self._allPardata = checkTable(parData)
    self._allChilddata = checkTable(childData)

    self._curParInd = checkNumber(parInd)
    self._curChildInd = checkNumber(childInd)

    if self._curParInd <= 0 then
        self._curParInd = 1
    end
    if self._curChildInd <= 0 then
        self._curChildInd = 1
    end

    self:InitData()
    self:FillSelf()
end

--仅用来刷新红点
function CommonTabToggleLeftExpand:RedPointRefresh()
    self._blackCb = true
    self:FillSelf()
end

function CommonTabToggleLeftExpand:InitData()
    local t = {}
    
    for k, v in pairs(self._allPardata) do
        v.isChild = false
        v.__ind = k
        table.insert(t, v)
        if k == self._curParInd then
            local _t = checkTable(self._allChilddata[k])
            for _k, _v in pairs(_t) do
                _v.isChild = true
                _v.__ind = _k
                table.insert(t, _v)
            end
        end
    end
    self._viewData = t
end 

function CommonTabToggleLeftExpand:FillSelf()
    if not self._isInitView then
        self._isInitView = true
        self.ListView:InitListView(table.count(self._viewData), Bind(self, self.OnRefreshIndex))
    else
        GameUtils.ReloadData(self.ListView, table.count(self._viewData))
    end
end 

function CommonTabToggleLeftExpand:OnRefreshIndex(listView, index)
    if index < 0 then
        return nil
    end

    local data = self._viewData[index + 1]
    local cellName 
    local isChild = checkBool(data.isChild)
    if isChild then
        cellName = ("Cell2")
    else
        cellName = ("Cell1")
    end

    local cell = listView:NewListViewItem(cellName)

    local scr = CfUtils.GetLuaScr(cell.gameObject, CommonTabToggleLeftExpandCell)
    if scr then
        scr:Refresh(data, function()
            if data.lock then
                GameUtils.Toast(data.lockToast)
                return--选中失败，直接返回
            end

                --local funcResult = data.func(data)
            --if funcResult == 0 then --选中失败时返回0，不切换选中状态
            --    return--选中失败，直接返回
            --end
            self._blackCb = false
            if isChild then
                if data.func then
                    data.func(data)
                end
                self:OnSelectChildNode(data, index)
            else
                self:OnSelectParNode(data, index)
            end
        end)

        --if not self._blackCb then
            if isChild then
                if self._curChildInd == data.__ind then
                    scr:RefreshSelect(true)
                    if not self._blackCb then
                        if data.func then
                            data.func(data)
                        end
                    end
                    self._curSelectInd = index
                end
            else
                if self._curParInd == data.__ind then
                    scr:RefreshSelect(true)
                    if not self._blackCb then
                        if data.func then
                            data.func(data)
                        end
                    end
                end
            end
        --end
    end

    return cell
end

function CommonTabToggleLeftExpand:OnSelectChildNode(data, ind)
    if not data then
        return
    end

    local go 
    if checkNumber(self._curSelectInd) > 0 then
        go = self.ListView:GetShownItemByItemIndex(self._curSelectInd)
        if go then
            local lastScr = CfUtils.GetLuaScr(go, CommonTabToggleLeftExpandCell)
            if lastScr then
                lastScr:RefreshSelect(false)
            end
        end
    end
    self._curSelectInd = ind
    self._curChildInd = data.__ind
    if checkNumber(self._curSelectInd) > 0 then
        go = self.ListView:GetShownItemByItemIndex(self._curSelectInd)
        if go then
            local lastScr = CfUtils.GetLuaScr(go, CommonTabToggleLeftExpandCell)
            if lastScr then
                lastScr:RefreshSelect(true)
            end
        end
    end
end

function CommonTabToggleLeftExpand:OnSelectParNode(data)
    if not data then
        return
    end
    --[[
    local go 
    if checkNumber(self._curSelectInd) > 0 then
        go = self.ListView:GetShownItemByItemIndex(self._curSelectInd)
        if go then
            local lastScr = CfUtils.GetLuaScr(go, CommonTabToggleLeftExpandCell)
            if lastScr then
                lastScr:RefreshSelect(false)
            end
        end
    end
    ]]
    --取消选中
    if checkNumber(data.__ind) == self._curParInd then
        return
        --self._curParInd = 0
    else
        self._curParInd = checkNumber(data.__ind) 
    end 
    self._curChildInd = 1
    self._curSelectInd = 0
    self:InitData()
    self:FillSelf()
end

function CommonTabToggleLeftExpand:MovePanelToIndex(index)
    self.ListView:MovePanelToItemIndex(index - 1)
end


function CommonTabToggleLeftExpand:OnDestroy()
    self.controller = nil--luabehaviour 中CSharp对象
    self:Delete()
    self = nil
end

return CommonTabToggleLeftExpand